def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-tat: donate if recipient has ever donated to me
    for entry in my_history:
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            if entry["partner_action"] == "donate":
                return True
    return False
